            variationData.isBreakCustomized = variationData.deductCustomBreakTime && variationData.doesBreakTimeOverlapAbsenceTimes && (dateHelp.convertTimeToMilitaryTime(variationData.breakStartTime) != dateHelp.convertTimeToMilitaryTime(absrStateVal.worker.defaultBreakStartTime) && dateHelp.convertTimeToMilitaryTime(variationData.absenceStartTime) != dateHelp.convertTimeToMilitaryTime(variationData.breakStartTime) || dateHelp.convertTimeToMilitaryTime(variationData.breakEndTime) != dateHelp.convertTimeToMilitaryTime(absrStateVal.worker.defaultBreakEndTime) && dateHelp.convertTimeToMilitaryTime(variationData.breakEndTime) != dateHelp.convertTimeToMilitaryTime(variationData.absenceEndTime));
            $scope.customBreakType = absrSvc.getBreakType(!variationData.doesBreakTimeOverlapAbsenceTimes, !variationData.deductCustomBreakTime, variationData.isBreakCustomized);
