          shouldShowAddSubsButton: function shouldShowAddSubsButton() {
            var result = addingSubsToPreferredList || vm.currentMode == vm.pageMode.commentEntry && vm.requireCommentsWhenExcludingSubs || vm.currentMode == vm.pageMode.subSelection && !vm.requireCommentsWhenExcludingSubs;
            return result;
          },
