        var strings = $scope.strings = stringSvc.getStrings(['Dashboard.Header.QuickActions.Label', 'Dashboard.Header.Button.Search', 'Dashboard.ConfirmationNumber.Input.Placeholder', 'Dashboard.Header.Button.CreateAbsence', 'Dashboard.Header.Button.CreateVacancy', 'Dashboard.Header.Button.Approve', 'Dashboard.Header.ButtonCaption.Approve', 'Dashboard.Header.Button.Reconcile', 'Dashboard.Header.ButtonCaption1.Reconcile', 'Dashboard.Header.ButtonCaption2.Reconcile', 'Dashboard.Header.ButtonCaption.NextXDays', 'Dashboard.Header.ButtonCaption.PastXDays', 'Dashboard.SearchDialog.FAQ.Message', 'AbsrIsNull']);

        // View Model properties
        var vm = $scope.vm = {
          searchText: null,
          isSearching: false,
          searchErrors: [],
          approvalCount: 0,
          reconciliationCount: 0,
          loadingApprovalCount: true,
          loadingReconciliationCount: true,
          approvalBadgeCaption: stringHelp.replace($scope.strings['Dashboard.Header.ButtonCaption.NextXDays'], '{0}', '<br>' + totalApprovalDays),
          reconcileBadgeCaption: stringHelp.replace($scope.strings['Dashboard.Header.ButtonCaption.PastXDays'], '{0}', '<br>' + totalReconcileDays),
          reconciliationLoadError: false,
          approvalRequestError: false
        };

        // Actions that can be bound to from the view
        var go = $scope.go = {
          search: function search() {
            toastHelp.clear();
            vm.searchErrors.length = 0;
            if (!vm.isSearching) {
              if (vm.searchText === null) {
                return null;
              }
              if (isNaN(vm.searchText)) {
                vm.searchErrors.push(strings['AbsrIsNull']);
                toastHelp.error(vm.searchErrors, 'Error');
                return null;
              }
              vm.isSearching = true;
              searchSvc.search(vm.searchText).then(function () {
                vm.isSearching = false;
              }, function () {
                vm.isSearching = false;
              });
            }
          }
        };
