    route.strings = stringSvc.getStrings(['Reports.Title.StaffList', 'Table.Header.Employee', 'Reports.Table.Header.LoginID', 'Reports.Table.Header.PIN', 'Reports.Table.Header.Identifier', 'Reports.Table.Header.Active', 'Reports.Table.Header.NeedsSub', 'Reports.Table.Header.AvgSubExp', 'Reports.Table.Header.Ratings', 'VacancyProfile', 'Phone', 'Yes', 'No', 'Optional', 'Summary', 'Report.Result.Label.NoFeedback', 'Reports.GroupSummary.Label.Emps', 'Reports.GroupSummary.Label.ActiveEmps', 'Reports.GroupSummary.Label.EmpsNeedingSubs', 'Reports.GroupSummary.Label.ItinerantEmps', 'Reports.GroupSummary.Label.VacProfs', 'Reports.GroupSummary.Label.ActiveVacProfs', 'Reports.GroupSummary.Label.VacProfsNeedingSubs', 'Reports.GroupSummary.Label.ItinerantVacProfs', 'NoRecordsFound', 'Reports.Results.Label.InitialInstructions', 'Reports.CriteriaPanel.Button.Print']);

