    route.strings = stringSvc.getStrings(['NoRecordsFound', 'Reports.Results.Label.InitialInstructions', 'Reports.Title.SubAvailability', 'Table.Header.Substitute', 'AvailableSub.Text.Excluded', 'SubPrefersLocation', 'Table.Header.PhoneNumber', 'Table.Header.Skills', 'Reports.CriteriaPanel.Button.Print', 'DR.Today', 'daysago', 'Day', 'Days', 'In', 'SubProfile.text.Email']);

