          if (canViewPayCode) {
            html = html + '<label>Pay Code:</label>';
            if (row.absences[i].payCode) {
              html = html + '<div>' + row.absences[i].payCode.description + '</div>';
            } else {
              html = html + '<div>None</div>';
            }
          }
